export const MarketTrendCandleProvenanceSource = {
  kite: "kite",
  yahoo: "yahoo",
  mixed: "mixed",
  none: "none",
} as const;

/**
 * Honest provenance for the INDEX intraday candles that fed the trend's index-rule contributions (Kite-first, Yahoo fallback). source=none means no index candles were available and those rules were skipped — never silently substituted.
 */
export type MarketTrendCandleProvenance = {
  /** kite = every index series came from Kite; yahoo = every series fell back to Yahoo; mixed = some of each; none = no index candles consumed. */
  source: MarketTrendCandleProvenanceSource;
  /** Timestamp of the freshest index bar consumed, or null when none. */
  asOf?: string | null;
  /** Whether the freshest index bar is within the 15-minute candle freshness budget. false means the trend is running on stale/no index candles. */
  fresh?: boolean;
  /** How many index series contributed candles. */
  indicesUsed?: number;
  /** Index series sourced from Kite. */
  kiteCount?: number;
  /** Index series sourced from the Yahoo fallback. */
  yahooCount?: number;
};

/**
 * Honest accounting of how complete the sector leadership/laggards aggregation is. Rows whose sector is missing or not part of the known sector partition are EXCLUDED and counted here, never silently dropped.
 */
export type MarketTrendSectorCoverage = {
  /** Total scanner rows considered for sector aggregation. */
  totalRows: number;
  /** Rows placed into a known sector bucket. */
  mappedRows: number;
  /** Rows excluded because their sector was missing or unmapped. */
  excludedUnmapped: number;
  /** mappedRows / totalRows as 0–100 (100 when no rows). */
  coveragePct: number;
  /** Plain-language explanation of the exclusion, or null when nothing was excluded. */
  reason?: string | null;
};

