/**
 * P0-00 LOCKED PLAN — the persisted, immutable trading plan from the lifecycle row. Spot levels lock at emission; option premiums lock once at the first successful enrichment backfill (premiumLockedAt) and NEVER change afterwards. Any legitimate correction must go through the option_signal_plan_audit ledger. This is the plan of record the card must render; live re-projections belong in liveMtm.
 */
export interface OptionSignalPlanSnapshot {
  /** When this exact signal was first emitted today (row generated_at). Never moves. */
  emittedAt: string;
  /** When spot first crossed the entry trigger. Null while PENDING. */
  triggeredAt?: string;
  /** Contract strike locked on the row at emission. If the live ATM strike has since drifted, liveMtm.strikeDrift is true and live premium projections are suppressed. */
  strike: number;
  /** CALL or PUT — locked at emission. */
  optionType: string;
  /** Signal tier at emission (HIGH_CONVICTION / BASELINE). */
  tier?: string;
  /** Confidence persisted at emission — does not follow later recalculations. */
  confidenceAtEmission: number;
  /** Locked spot entry level. */
  entrySpot: number;
  /** Locked spot stop level. */
  stopSpot: number;
  /** Locked spot target 1. */
  target1Spot: number;
  /** Locked spot target 2. */
  target2Spot: number;
  /** Locked entry trigger condition text. */
  entryTrigger?: string;
  /** PLANNED option entry premium (₹/share) locked at emission-cycle enrichment. Null on legacy rows or when the chain was unavailable — never fabricated. The actual paper fill may differ (see paperFill). */
  entryPremiumPlanned?: number;
  /** Planned (locked) option stop premium. */
  stopPremiumPlanned?: number;
  /** Planned (locked) option T1 premium. */
  target1PremiumPlanned?: number;
  /** Planned (locked) option T2 premium. */
  target2PremiumPlanned?: number;
  /** When the premium plan was persisted (one-shot backfill). Null on legacy rows. */
  premiumLockedAt?: string;
  /** True when this row pre-dates premium locking (no locked premiums and no premiumLockedAt). The card shows a LEGACY_PLAN_FIELDS warning instead of pretending live projections are the plan. */
  legacyPlanFields: boolean;
}

/**
 * P0-00 LIVE MTM — current market view that updates every poll: live spot, live option LTP and live Greeks-projected premiums for the CURRENT ATM strike. These are explicitly NOT the plan and never overwrite planSnapshot.
 */
export interface OptionSignalLiveMtm {
  /** Most recent observed spot. */
  currentSpot?: number;
  /** Live premium of the live strike (liveStrike), not necessarily the locked plan strike. */
  optionLtp?: number;
  /** Strike of the live enrichment leg. When it differs from planSnapshot.strike (ATM moved intra-day), strikeDrift is true. */
  liveStrike?: number;
  /** True when liveStrike !== planSnapshot.strike. Live premium projections below are suppressed (null) in that case because they would price a different contract than the locked plan. */
  strikeDrift?: boolean;
  /** Live Greeks-projected premium at the locked spot entry. Display-only. Null when strikeDrift. */
  entryPremiumLive?: number;
  /** Live projected premium at the locked spot stop. Null when strikeDrift. */
  stopPremiumLive?: number;
  /** Live projected premium at locked spot T1. Null when strikeDrift. */
  target1PremiumLive?: number;
  /** Live projected premium at locked spot T2. Null when strikeDrift. */
  target2PremiumLive?: number;
  /** Wall-clock time of this live view (signal cycle time). */
  lastUpdatedAt: string;
}

/**
 * P0-00: the actual paper-trade FILL for this signal today, from the paper_trade_fo row (locked at open, immutable). Present only when the auto-trader opened a trade. Plan (planSnapshot) vs fill divergence is expected and honest — the fill happens at the live premium of the trigger tick.
 */
export interface OptionSignalPaperFill {
  /** Premium actually paid at paper open (₹/share). */
  entryPremium: number;
  openedAt: string;
  /** Paper trade status (OPEN / CLOSED). */
  status: string;
}

export interface OptionSignal {
  index: string;
  indexName: string;
  spot: number;
  /** Intraday session change from today's open (vs open). Used internally for momentum direction. Label as 'vs open' if displayed alongside prevClose-based change. */
  spotChangePercent?: number;
  /** Canonical change % vs previous session close — the standard market convention. Use this for display. Null when daily series has < 2 bars. */
  spotChangePctVsPrevClose?: number;
  /** Previous completed session close used to compute spotChangePctVsPrevClose. */
  spotPrevClose?: number;
  bias: OptionSignalBias;
  confidence: number;
  /** HIGH_CONVICTION fires from a named setup; BASELINE is the always-on directional read. */
  tier?: OptionSignalTier;
  /** FNO_SIGNAL_HYGIENE_V2: TRADEABLE only for STANDARD-tier HIGH_CONVICTION signals the auto-trader may open; INFO_ONLY for BASELINE and any demoted/vetoed (RECOVERY_MODE_VETO / CHASE_RISK_VETO) signal, which is surfaced for context but never auto-traded. */
  tradeClass?: OptionSignalTradeClass;
  /** e.g. intraday-15m */
  timeframe?: string;
  vwap?: number;
  /** True when vwap is a genuine volume-weighted average price. False for cash indices (NIFTY/BANKNIFTY/SENSEX) whose Kite candles carry zero volume — vwap is set to spot as a geometric placeholder and must not be displayed as institutional fair value. */
  vwapAvailable?: boolean;
  ema9?: number;
  ema21?: number;
  /** Phase-2: intraday EMA20 — confluence-engine input alongside EMA9/EMA50. */
  ema20?: number;
  /** Phase-2: intraday EMA50 — slower trend filter for the confluence engine. */
  ema50?: number;
  rsi?: number;
  /** DAILY-bar volume profile VAH (legacy). Null for cash indices (zero volume). */
  valueAreaHigh?: number;
  /** DAILY-bar volume profile VAL (legacy). Null for cash indices (zero volume). */
  valueAreaLow?: number;
  /** DAILY-bar volume profile POC (legacy). Null for cash indices (zero volume). */
  pointOfControl?: number;
  /** Phase-2: INTRADAY fixed volume profile VAH (last 60 15-min bars). Null for cash-index spots whose intraday volume is 0. */
  intradayValueAreaHigh?: number;
  /** Phase-2: INTRADAY fixed volume profile VAL. */
  intradayValueAreaLow?: number;
  /** Phase-2: INTRADAY fixed volume profile POC. */
  intradayPointOfControl?: number;
  /** Phase-3 confluence-engine score (sum of EMA-stack/VWAP/VolumeProfile/Regime/IVR factor weights, roughly -30..+20). Added to the detector's raw confidence before the HC emission floor; positive = confluence supports the bias, negative = opposed. */
  confluenceScore?: number;
  /** Higher-timeframe EMA50 used for HTF bias. */
  dailyEma50?: number;
  /** Daily-timeframe bias derived from spot vs daily EMA50. */
  htfBias?: OptionSignalHtfBias;
  /** True if intraday signal direction opposes the daily HTF bias. */
  htfConflict?: boolean;
  /** Status tags e.g. HTF_CONFLICT, RR_LOW, EXTENDED, BASELINE. */
  tags?: string[];
  /** Type of intraday setup */
  setupKey?: OptionSignalSetupKey;
  /** Human-readable setup label */
  setupName?: string;
  /** One-line trade idea explanation */
  setupSummary?: string;
  /** Honest entry trigger condition. The paper engine uses touch semantics: CALL fires when bar high or live tick >= entry; PUT fires when bar low or live tick <= entry. The candle does NOT need to close at the level. */
  entryTrigger?: string;
  /** TOUCH_OR_TICK: entry fires when bar high/low or live tick reaches the entry level — the candle does not need to close there. CLOSE_CONFIRMED: reserved for future setups that explicitly require a candle close at the level. All current F&O paper engine setups use TOUCH_OR_TICK. */
  triggerSemantics?: OptionSignalTriggerSemantics;
  leg: OptionLeg;
  drivers: SignalReason[];
  invalidation?: string;
  generatedAt: string;
  /** Live lifecycle state vs locked entry/SL/targets. */
  status?: OptionSignalStatus;
  /** When this exact (date+index+setup+direction) signal was first emitted today; persisted, never moves. */
  firstSeenAt?: string;
  /** First time spot crossed the entry trigger in trade direction. */
  triggeredAt?: string;
  /** Time the trade was closed by stop, target, or session end. */
  exitedAt?: string;
  /** Reason the lifecycle row exited. STALE_TRIGGER is a Phase-1 quality gate for PENDING rows whose trigger has not fired within ~45 minutes — the level is no longer relevant to the live tape. */
  exitReason?: OptionSignalExitReason;
  exitPrice?: number;
  /** Maximum points moved in trade's favour from entry, observed today. */
  maxFavorableExcursionPts?: number;
  /** Maximum points moved against trade from entry, observed today. */
  maxAdverseExcursionPts?: number;
  /** Most recent observed spot used to evaluate this signal. */
  lastSpot?: number;
  /** Wall-clock time the lifecycle was last evaluated against live spot. Surfaced on the card so the user can verify the trigger pipeline is alive — not stuck on stale data. */
  lastEvaluatedAt?: string;
  /** Current premium (₹/share) of the option at the chosen strike — CE for BULLISH, PE for BEARISH. Sourced from Kite or NSE option chain when available. */
  optionLtp?: number;
  /** Greeks-projected option premium at the spot entry trigger. Equals optionLtp + delta×(spotEntry − spot). What the trader will likely pay if the trigger fires now. */
  optionEntry?: number;
  /** Greeks-projected option premium at the spot target 1. Equals optionEntry + delta×(spotT1 − spotEntry). */
  optionTarget1?: number;
  /** Greeks-projected option premium at the spot target 2. */
  optionTarget2?: number;
  /** Greeks-projected option premium at the spot stop. Floored at 0.05 ₹/share so it never goes negative. */
  optionStopLoss?: number;
  /** Delta of the chosen strike at signal time. Used to translate spot moves into option moves. */
  optionDelta?: number;
  /** Theta (₹/share/day, time decay) of the chosen strike. */
  optionTheta?: number;
  /** Vega (₹/share per 1 vol point) of the chosen strike. */
  optionVega?: number;
  /** Data quality label indicating the source and freshness of intraday data used to generate this signal. */
  dataQuality?: OptionSignalDataQuality;
  /** Provider that produced the option premium/OI behind optionEntry/optionStopLoss/optionTarget*. Only 'kite' is trusted to power an OFFICIAL F&O signal or paper trade; nse/yahoo/unknown are display-only fallbacks. */
  premiumSource?: OptionSignalPremiumSource;
  /** True only when the option premium came from a complete, non-stale, non-expired Kite chain. When false the signal is demoted to INFO_ONLY and may never auto-open a paper trade. */
  premiumTrusted?: boolean;
  /** Concrete reason the option premium is NOT Kite-trusted (e.g. NSE fallback, stale, missing). Present only when premiumTrusted is false. */
  premiumWarning?: string;
  /** Phase-1 regime classification for the index at signal time. Read-only label — does not gate setup emission yet (Phase-2 will use it to route setup eligibility). */
  regime?: OptionSignalRegime;
  /** Plain-English explanation for the regime label. UI surfaces verbatim under the regime badge. */
  regimeReason?: string;
  /**
   * ATM IV-rank over the trailing 252 sessions (0-100). 0 = today's IV is the lowest; 100 = highest. Null when sample <5 days.
   * @minimum 0
   * @maximum 100
   */
  ivRank?: number;
  /**
   * Fraction of trailing-252 sessions whose ATM IV was strictly below today's, expressed 0-100. Null when sample <5 days.
   * @minimum 0
   * @maximum 100
   */
  ivPercentile?: number;
  planSnapshot?: OptionSignalPlanSnapshot;
  liveMtm?: OptionSignalLiveMtm;
  /** P0-00: true only when this signal has one or more rows in the append-only option_signal_plan_audit ledger (a sanctioned, non-silent plan correction). Renders a 'plan revised' warning on the card. Always false today — no automated path writes the ledger. */
  planRevised?: boolean;
  paperFill?: OptionSignalPaperFill;
}

export type OptionSignalDiagnosticsSuppressedItem = {
  index: string;
  reasons: string[];
};

/**
 * Phase-1 quality-gate state for the current cycle. Surfaced so the UI banner can show why live cards are missing on a given session (circuit breaker after consecutive stops, VIX spike, correlated-exposure dedupe, OI veto, etc.).
 */
export type OptionSignalDiagnosticsGates = {
  /** True when stoppedToday >= stopLimit. New high-conviction emission is suspended for the rest of the session. */
  circuitBreakerActive: boolean;
  /** Number of STOPPED outcomes recorded for today (IST date). */
  stoppedToday: number;
  /** FNO_SIGNAL_HYGIENE_V2: actual executed paper-trade stops today (CLOSED paper_trade_fo, exit_reason STOPPED). Drives the circuit breaker when the flag is ON. */
  paperStoppedToday?: number;
  /** Modeled signal-history STOPPED count for today (IST date) — diagnostic only; equals stoppedToday. */
  modeledStoppedToday?: number;
  /** Daily stop limit that triggers the circuit breaker. */
  stopLimit: number;
  /** True when India VIX has tripped either the intraday or day-over-day spike threshold. */
  vixSpike: boolean;
  /** India VIX percent move from session open. Null when intraday VIX data is unavailable. */
  vixIntradayPct?: number | null;
  /** India VIX percent move vs prior daily close. Null when daily VIX data is unavailable. */
  vixDayPct?: number | null;
  /** Human-readable description of which VIX threshold tripped, if any. */
  vixSpikeReason?: string | null;
  /** How many high-conviction signals were suppressed in this cycle by the correlated-exposure cap (BROAD / BANK buckets keep only the highest-confidence card per direction). */
  correlationDroppedCount: number;
  /** How many high-conviction signals were hard-vetoed this cycle because OI sentiment opposed the trade direction with magnitude above the veto threshold. */
  oiVetoCount: number;
  /** How many PENDING lifecycle rows were expired this cycle by the stale-trigger sweep. */
  staleExpiredCount: number;
  /** Plain-English lines describing every active gate. UI banner reads these verbatim. */
  notes: string[];
};

export interface OptionSignalDiagnostics {
  indicesConfigured: number;
  indicesWithBars: number;
  highConvictionCount: number;
  baselineCount: number;
  /** Per-index report of why no high-conviction setup fired. */
  suppressed: OptionSignalDiagnosticsSuppressedItem[];
  /** Phase-1 quality-gate state for the current cycle. Surfaced so the UI banner can show why live cards are missing on a given session (circuit breaker after consecutive stops, VIX spike, correlated-exposure dedupe, OI veto, etc.). */
  gates?: OptionSignalDiagnosticsGates;
}

/**
 * OPEN=during session, BEFORE_OPEN=before 09:15 IST, PRE_OPEN=09:00–09:15 IST, AFTER_CLOSE=after 15:30 IST, WEEKEND=Sat/Sun, HOLIDAY=NSE holiday, UNKNOWN=internal error.
 */
export type FnoMarketStatusReason =
  (typeof FnoMarketStatusReason)[keyof typeof FnoMarketStatusReason];

export const FnoMarketStatusReason = {
  OPEN: "OPEN",
  BEFORE_OPEN: "BEFORE_OPEN",
  PRE_OPEN: "PRE_OPEN",
  AFTER_CLOSE: "AFTER_CLOSE",
  WEEKEND: "WEEKEND",
  HOLIDAY: "HOLIDAY",
  UNKNOWN: "UNKNOWN",
} as const;

/**
 * Rich NSE market-hours status. Always returned with /options/signals. Use marketOpen (boolean) for gating, reason for display.
 */
export interface FnoMarketStatus {
  /** True when the IST calendar date is a weekday and not an NSE holiday. */
  isTradingDay: boolean;
  /** True only during 09:15–15:30 IST on a trading day. */
  marketOpen: boolean;
  /** OPEN=during session, BEFORE_OPEN=before 09:15 IST, PRE_OPEN=09:00–09:15 IST, AFTER_CLOSE=after 15:30 IST, WEEKEND=Sat/Sun, HOLIDAY=NSE holiday, UNKNOWN=internal error. */
  reason: FnoMarketStatusReason;
  /** Server wall-clock time (UTC) when status was computed. */
  serverUtc: string;
  /** Server time converted to IST (HH:MM DD-Mon-YYYY). */
  serverIst: string;
  /** Always Asia/Kolkata. */
  exchangeTimezone: string;
  /** Session open time in IST. Always 09:15. */
  openTimeIst: string;
  /** Session close time in IST. Always 15:30. */
  closeTimeIst: string;
  /** Source of the holiday calendar used. */
  calendarSource: string;
  /** Date through which the holiday calendar is valid. */
  calendarAsOf: string;
}

