/**
 * Stage 4: Itemised F&O round-trip costs for one trade (NSE rates, effective 2026-04-01).
 */
export interface FnoCostBreakdown {
  /** Flat brokerage × 2 orders. ₹ */
  brokerage: number;
  /** STT on exit (sell) leg: 0.05% of exit premium × qty. ₹ */
  stt: number;
  /** NSE exchange transaction charge on both legs. ₹ */
  exchangeTxn: number;
  /** SEBI turnover charge on both legs. ₹ */
  sebiCharges: number;
  /** 18% GST on (brokerage + exchangeTxn + sebiCharges). ₹ */
  gst: number;
  /** Stamp duty on buy (entry) leg. ₹ */
  stampDuty: number;
  /** Bid-ask half-spread cost for both legs. Null when not applicable. ₹ */
  spreadCost?: number | null;
  /** True when real bid/ask unavailable and a default 0.5% spread was used. */
  spreadModelled: boolean;
  /** Sum of all cost items. ₹ */
  total: number;
}

/**
 * Itemised F&O round-trip charges for one backtest trade (Modes A, B, C). Mode D uses FnoCostBreakdown via the costs field.
 */
export interface BacktestTradeCostResult {
  /** true when all required inputs were present and charges could be computed. */
  computable: boolean;
  /** true when entry/exit premiums were estimated from entry spot (Modes B/C). false when real captured premiums were used (Mode A). */
  premiumModeled: boolean;
  /** Gross P&L before charges. */
  grossPnl?: number | null;
  /** Flat ₹20 round-trip brokerage per order side × 2. ₹ */
  brokerage: number;
  /** STT: 0.15% on exit (sell) premium turnover. ₹ */
  stt: number;
  /** NSE exchange transaction charges on both legs. ₹ */
  exchangeCharges: number;
  /** SEBI charges on both legs. ₹ */
  sebiCharges: number;
  /** Stamp duty on buy-side premium turnover. ₹ */
  stampDuty: number;
  /** 18% GST on (brokerage + exchange + SEBI). ₹ */
  gst: number;
  /** Bid-ask spread + fill slippage (35 bps per side of premium turnover). ₹ */
  slippageCost: number;
  /** Sum of all charges. ₹ */
  totalCharges: number;
  /** Net P&L = grossPnl − totalCharges. */
  netPnl?: number | null;
}

